const body = $input.item.json.body;

if (!body) return [];

const fromMe = body.fromMe || false;
const from = body.phone || '';
const messageText = body.text?.message || '';

if (fromMe || !from || !messageText) return [];

return [{
  json: {
    telefone: from,
    message: messageText,
    messageType: 'text',
    instanceName: 'hormone-clinica'
  }
}];

const leads = $input.item.json;
const telefone = $('Extrair Mensagem').item.json.telefone;
const message = $('Extrair Mensagem').item.json.message;

let lead = Array.isArray(leads) ? leads[0] : null;
let isNew = false;

if (!lead) {
  isNew = true;
  lead = {
    telefone: telefone,
    etapa: 1,
    temperatura: 'morno',
    historico: [],
    dor_principal: null,
    nome: null,
    contexto: null
  };
}

const historico = lead.historico || [];
historico.push({ role: 'user', content: message, ts: new Date().toISOString() });

return [{
  json: {
    ...lead,
    telefone,
    message,
    isNew,
    historico
  }
}];

const claudeResponse = $input.item.json;
const lead = $('Montar Prompt').item.json;

let resposta = '';
let proximaEtapa = lead.etapa;
let dorPrincipal = lead.dor_principal;
let nomeLead = lead.nome;

try {
  const content = claudeResponse.content?.[0]?.text || '';
  const parsed = JSON.parse(content);
  resposta = parsed.resposta || content;
  proximaEtapa = parsed.proxima_etapa || lead.etapa;
  if (parsed.dor_principal) dorPrincipal = parsed.dor_principal;
  if (parsed.nome_lead) nomeLead = parsed.nome_lead;
} catch (e) {
  resposta = claudeResponse.content?.[0]?.text || 'Desculpe, tive um problema. Pode repetir?';
}

const historico = lead.historico || [];
historico.push({ role: 'assistant', content: resposta, ts: new Date().toISOString() });

return [{
  json: {
    ...lead,
    resposta,
    proxima_etapa: proximaEtapa,
    dor_principal: dorPrincipal,
    nome: nomeLead,
    historico
  }
}];
